query:
DELETE FROM users WHERE id IN (
  SELECT id FROM (
    SELECT u1.id 
    FROM users u1
    WHERE EXISTS (
      SELECT 1 FROM users u2 
      WHERE u2.email = u1.email 
      AND u2.id > u1.id
    )
    AND u1.email IN ('chris@ewandf.ca', 'pat@ewandf.ca', 'russ@ewandf.ca', 'markus@ewandf.ca', 'tony@ewandf.ca')
  ) AS duplicates
);

